#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    double D;
    if (scanf("%d %lf", &n, &D) != 2) return 0;
    vector<double> P(n), C(n);
    for (int i = 0; i < n; i++) {
        scanf("%lf %lf", &P[i], &C[i]);
    }

    // dp[i] = tempo mínimo para chegar à posição P[i] acabando de pegar a bateria i
    // Transição: usar a bateria j do trecho P[j] -> P[i] custa (P[i]-P[j])^2 / C[j]
    // (velocidade ótima no trecho de comprimento d com carga C: V = C/d, tempo d/V = d^2/C)
    const double INF = 1e18;
    vector<double> dp(n, INF);
    dp[0] = 0.0;
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (dp[j] >= INF) continue;
            double d = P[i] - P[j];
            double cost = dp[j] + d * d / C[j];
            if (cost < dp[i]) dp[i] = cost;
        }
    }

    // Último trecho: de P[j] até D usando a bateria j (troca possível em qualquer bateria)
    double ans = INF;
    for (int j = 0; j < n; j++) {
        if (dp[j] >= INF) continue;
        double d = D - P[j];
        double cost = dp[j] + d * d / C[j];
        if (cost < ans) ans = cost;
    }

    printf("%.3f\n", ans);
    return 0;
}
